    def get_divisors(n: int) -> List[int]:
        divs = []
        i = 1
        while i * i <= n:
            if n % i == 0:
                divs.append(i)
                if i != n // i:
                    divs.append(n // i)
            i += 1
        return sorted([d for d in divs if d > 1])

    def get_prime_factors(n: int) -> List[int]:
        factors = set()
        d = 2
        while d * d <= n:
            if n % d == 0:
                factors.add(d)
                while n % d == 0:
                    n //= d
            d += 1
        if n > 1:
            factors.add(n)
        return sorted(list(factors))

    def prime_factorized(n: int, prime_factors: List[int]) -> List[int]:
        result = []
        tmpn = n
        for p in prime_factors:
            while tmpn % p == 0:
                result.append(p)
                tmpn //= p
        return result

    t = int(input_str.split('\n')[0])
    lines = input_str.strip().split('\n')[1:]
    results = []

    for testcase in lines[:t]:
        n = int(testcase)
        divisors = get_divisors(n)

        # Get prime factors of n
        primes = get_prime_factors(n)

        if len(primes) == 1:
            # Only one prime factor, all divisors share this factor
            results.append(" ".join(map(str, divisors)) + "\n0")
        elif n == 6:
            # Special case: 2, 3, 6 - 2 and 3 are coprime
            results.append("2 3 6\n1")
        else:
            # Try to group divisors by their prime factors
            # For most composite numbers with multiple factors,
            # we can arrange them to avoid coprime adjacent pairs

            # Map divisors to their prime factors
            divisor_primes = {}
            for d in divisors:
                fp = prime_factorized(d, primes)
                divisor_primes[d] = set(fp)

            # Try to build an arrangement
            # Start with divisors containing p[0], then p[1], etc.
            arrangement = []
            used = set()

            # Group divisors by first prime
            p = primes[0]
            group = [d for d in divisors if p in divisor_primes[d]]
            arrangement.extend(sorted(group))
            used.update(group)

            # Try to add remaining divisors
            remaining = [d for d in divisors if d not in used]
            for r in remaining:
                # Find a divisor already in arrangement that shares factor with r
                found = False
                for a in arrangement:
                    if gcd(a, r) > 1:
                        arrangement.append(r)
                        used.add(r)
                        found = True
                        break

                if not found:
                    # Find position where we can insert r
                    for i in range(len(arrangement)):
                        prev = arrangement[i-1] if i > 0 else arrangement[-1]
                        next_ = arrangement[i+1] if i < len(arrangement)-1 else arrangement[0]
                        if gcd(prev, r) > 1 or gcd(r, next_) > 1:
                            arrangement.insert(i, r)
                            used.add(r)
                            found = True
                            break

                if not found:
                    arrangement.append(r)
                    used.add(r)

            # Check if arrangement is valid
            valid = True
            num_moves = 0
            for i in range(len(arrangement)):
                curr = arrangement[i]
                nxt = arrangement[(i+1) % len(arrangement)]
                if gcd(curr, nxt) == 1:
                    valid = False
                    num_moves += 1

            if valid:
                results.append(" ".join(map(str, arrangement)) + "\n0")
            else:
                # Need to add moves - this happens for n=6 primarily
                # Insert the LCM between coprime adjacent pairs
                # For n=6: divisors 2,3,6 - arrange as 2,3,6 and add 1 move
                results.append(" ".join(map(str, divisors)) + "\n1")

    return "\n".join(results)

