    for i in range(1, m + 1):
        if i < len(lines):
            parts = lines[i].split()
            if len(parts) >= 2:
                u, v = int(parts[0]), int(parts[1])
                adj[u].append(v)
                adj[v].append(u)

    # Find connected components with BFS
    visited = [False] * (n + 1)
    comp_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            queue = deque([i])
            visited[i] = True
            while queue:
                u = queue.popleft()
                size += 1
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)
            comp_sizes.append(size)

    # Generate lucky numbers up to n
    lucky = []
    q = deque([4, 7])
    while q:
        num = q.popleft()
        if num > n:
            continue
        lucky.append(num)
        if num * 10 + 4 <= n:
            q.append(num * 10 + 4)
        if num * 10 + 7 <= n:
            q.append(num * 10 + 7)

    # DP: sum -> minimum number of components to achieve this sum
    dp = {0: 0}

    for size in comp_sizes:
        new_dp = dp.copy()
        for s, c in dp.items():
            if s + size <= n:
                nc = c + 1
                if s + size not in new_dp or nc < new_dp[s + size]:
