    count = 0
    for a2 in range(l, r + 1):
        a2_sq = a2 * a2

        # a1 must satisfy: a1 * a3 = a2^2, l <= a1 < a2, l <= a3 <= r
        # a1 must be at least max(l, ceil(a2^2/r))
        # a1 must be at most a2 - 1 (for a3 > a2) or at most min(a2^2//l - 1, r)

        a1_min = (a2_sq + r - 1) // r  # ceil(a2^2 / r)
        a1_min = max(l, a1_min)
