        a1_max = min(a1_max, r)

        for a1 in range(a1_min, min(a1_max, a2)):
            if a2_sq % a1 == 0:
                a3 = a2_sq // a1
                if l <= a3 <= r and a1 != a3 and a2 != a1 and a2 != a3:
                    count += 1

    return str(count)

