def count_factors(n):
    """Count factors of 2 and 5 in n."""
    if n == 0:
        return 0, 0
    c2 = 0
    c5 = 0
    temp = n
    while temp > 0 and temp % 2 == 0:
        c2 += 1
        temp //= 2
    while temp > 0 and temp % 5 == 0:
        c5 += 1
        temp //= 5
    return c2, c5

