def solution(input_str):
    MOD = 10**9 + 7

    n, k = map(int, input_str.strip().split())

    if n == 1:
        return "0"

    if k == 1:
        return str((n - 1) ** 2 % MOD)

    # Compute: E[f^2] = (n-1) * sum_{i=1}^{n-2} k^{-i} + k^{-(n-1)}
    # sum_{i=1}^{n-2} k^{-i} = (k^{n-2} - 1) / ((k^{n-1} * (k-1)))

    numerator = (pow(k, n - 2, MOD) - 1 + MOD) % MOD
    denominator_inv = pow(k - 1, MOD - 2, MOD)
    inv_k_n1 = pow(pow(k, n - 1, MOD), MOD - 2, MOD)

    sum_geo = numerator * denominator_inv % MOD * inv_k_n1 % MOD

    result = ((n - 1) * sum_geo + pow(k, MOD - 2, MOD)) % MOD

    return str(result)

