    """Check if (x,y) is on the border of axis-aligned square starting at (r,c) with size"""
    if not (r <= x < r + size and c <= y < c + size):
        return False
    return x == r or x == r + size - 1 or y == c or y == c + size - 1


def is_axis_square(x, y, r, c, size):
    """Check if (x,y) should be 1 for axis-aligned square"""
    return is_at_border_pos(x, y, r, c, size)


