    """Check if (x,y) is interior of axis-aligned square"""
    if not (r <= x < r + size and c <= y < c + size):
        return False
    return not (x == r or x == r + size - 1 or y == c or y == c + size - 1)


def is_valid_axis_square(r, c, size, n, m, matrix):
    """Check if there's a valid axis-aligned square"""
