        for y in range(c, c + size):
            if is_axis_square(x, y, r, c, size):
                if matrix[x][y] != 1:
                    return False

    # Check interior is all 0s (no 1s inside)
    for x in range(r + 1, r + size - 1):
        for y in range(c + 1, c + size - 1):
            if is_interior(x, y, r, c, size):
                if matrix[x][y] == 1:
                    return False

