    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    A = list(map(int, lines[1].split()))

    # Check if current array has value >= k
    if max(A) >= k:
        return "0\n"

    def binom_coeff(n, k_val):
        """Compute C(n, k_val) with overflow protection"""
        if k_val < 0 or k_val > n:
            return 0
        if k_val == 0:
            return 1
        # Use symmetry C(n,k) = C(n, n-k)
        k_val = min(k_val, n - k_val)

        result = 1
        for i in range(k_val):
            result = result * (n - i) // (i + 1)
            # Cap at slightly above k since we're comparing
            if result >= k:
                return result
            if result > 5000000000000000000:  # > 5e18 to avoid overflow
                return k

        return result

    def check(i):
        """Check if after i iterations, any element >= k"""
        total = 0
        for j in range(n):
            if A[j] == 0:
                continue

            # Coefficient for A[j] at iteration i is C(i + j, j)
            coeff = binom_coeff(i + j, j)

            contrib = A[j] * coeff
            if contrib >= k:
                return True

            total += contrib
            if total >= k:
                return True

        return total >= k

    # Binary search for minimum i
    left, right = 0, 1000

    # Safety check - should not need this with k <= 10^18
    # but good for edge cases
    if not check(right):
        right = 2000

    while left <= right:
