    if n == 0:
        return 0

    # memoization
    memo = {}

    def dp(left, right, current_min):
        if left > right:
            return 0

        state = (left, right, current_min)
        if state in memo:
            return memo[state]

        # Option 1: Use type 2 on all elements in range
        cost_type2 = right - left + 1

        # Option 2: Use type 1 on range [left, right]
        # Type 1 removes 1 from each position where count > 0
        m = min(nums[left:right+1])
