def dp_left_to_right(nums):
    n = len(nums)
    if n == 0:
        return 0

    memo = {}

    def helper(left, right, current_min):
        if left > right:
            return 0

        state = (left, right, current_min)
        if state in memo:
            return memo[state]

        # Take minimum across range
        if right < left:
            m = current_min
        else:
            m = min(nums[left:right+1])

        if m == 0:
            # Must use type 2
            result = right - left + 1
