            prefixes.add(s[:i])

    if not prefixes or k == 0:
        # No prefixes available or no speed dials
        return str(sum(len(s) * m for s, m in phone_numbers))

    def calculate_cost(prefix):
        """Calculate total cost when prefix is assigned to a speed dial."""
        cost = 0
        for s, m in phone_numbers:
            if s == prefix:
                # Exact match: 0 presses
                continue
            elif s.startswith(prefix):
                # Prefix match: enter remaining digits
                cost += (len(s) - len(prefix)) * m
            else:
                # No match: enter full number
                cost += len(s) * m
        return cost

    # Collect all costs
    all_costs = [calculate_cost(p) for p in prefixes]

    # Find minimum cost among prefixes (when k=1, pick best)
    if k >= len(all_costs):
        return str(min(all_costs) if all_costs else str(sum(len(s) * m for s, m in phone_numbers)))
    else:
        # Pick k best prefixes (smallest costs)
        sorted_costs = sorted(all_costs)
        return str(sum(sorted_costs[:k]))


